   const DC=new Map();L.forEach(z=>{const k=z.ts?isoOfTs(z.ts):'old',o=DC.get(k)||{n:0,t:0};o.n++;if(!tlDone(z)&&!z.undone)o.t++;DC.set(k,o)});
