    const w=XLSX.utils.aoa_to_sheet(a);w['!cols']=[{wch:6},{wch:22},{wch:12},{wch:16},{wch:14},{wch:18},{wch:20},{wch:30},{wch:16},{wch:16},{wch:14},{wch:14}];
