function moveTo(ids,fromP,src,toP,quiet){const P=parts(),sent=!!(fromP&&fromP.sent);let to=toP&&toP!=='new'?toP:null;
  if(!to&&toP!=='new')to=P.find(z=>z!==fromP&&!!z.sent===sent&&(!sent||z.bid===fromP.bid)&&String(z.src.id)===String(src.id));
  if(!to){to={id:nid++,src:{id:src.id,name:src.name,bank:src.bank||'',limit:0},method:'manual',param:{},ids:[],sent,at:new Date().toISOString()};if(sent)to.bid=fromP.bid;addPart(to)}
  ids.forEach(id=>{if(fromP)fromP.ids=fromP.ids.filter(z=>z!==id);if(!to.ids.includes(id))to.ids.push(id);if(sent){const b=batches.find(x=>x.id===fromP.bid),it=b&&b.items.find(x=>x.id===id);if(it){it.src=src.name;it.pid=to.id}}});
  if(fromP&&!fromP.ids.length)delPart(fromP);saveD();saveB();alloc=null;if(!quiet)logA('split',fromP?'انتقال به منبع دیگر':'تخصیص به منبع',fmt(ids.length)+' واریزی | '+(fromP?fromP.src.name+' ← ':'')+src.name);return to}
let mvIds=[],mvFrom=null;
function moveSheet(ids,title,fromP){bkAllocSync();mvIds=ids;mvFrom=fromP?fromP.id:null;const p=fromP,L=DSRC().filter(x=>!p||String(x.id)!==String(p.src.id));
   
  const one=ids.length===1?validated().find(r=>String(r.id)===String(ids[0])):null,F1=one?famOf(one):[],canPs=one&&can('split')&&!one.full&&one.level<2&&sources.length>1&&!F1.some(r=>r.sentBid);
  sheet(`<div class="sh-h"><div><b>${p?'انتقال به منبع دیگر':'تخصیص به منبع'}</b><small class="shsub">${esc(title)}</small></div><button class="x" data-act="close" aria-label="بستن">×</button></div>
  ${one&&!canPs&&one.id===famRoot(one)&&p&&p.sent?unsentRowsHTML(one):''}
  ${canPs&&one.id===famRoot(one)?`<button class="acrow mvps" data-act="pkFrom" data-id="${one.id}"><span class="bkb lg mvpsi">${ic('split')}</span><span class="tx"><b>بخشی از مبلغ از بانک دیگر</b><small>${F1.length>1?toFa(F1.length-1)+' بخش دیگر دارد · ':''}مبلغ را بزنید؛ از این منبع کم و جدا ارسال می‌شود</small></span>${ic('back').replace('class="i"','class="i flip"')}</button><div class="mvor"><span>یا همه مبلغ از یک منبع</span></div>`:''}
  ${L.length?`<div class="mvl">${L.map(x=>{const bk=acBank(x),inDay=parts().filter(z=>String(z.src.id)===String(x.id)),n=inDay.reduce((s2,z)=>s2+z.ids.length,0);const ok=inDay.filter(z=>!!z.sent===!!(p&&p.sent));return `<div class="mvs"><button class="acrow" data-act="mvGo" data-s="${x.id}">${bk?bankBadge(bk,'lg'):`<span class="bkb lg" style="--bc:#64748b">${esc(userInit(x.name))}</span>`}<span class="tx"><b>${esc(x.name)}</b><small>${esc(bkSub(x))}${n?'، '+fmt(n)+' واریزی در این لیست':''}${inDay.length>1?'، '+toFa(inDay.length)+' مرحله':''}</small></span>${ic('back').replace('class="i"','class="i flip"')}</button>${inDay.length>1||(inDay.length&&ok.length<inDay.length)?`<div class="mvr">${inDay.map((z,k)=>ok.includes(z)?`<button class="tch" data-act="mvGo" data-s="${x.id}" data-p="${z.id}">مرحله ${toFa(k+1)} <i>${toFa(z.ids.length)}</i></button>`:`<span class="tch dis">مرحله ${toFa(k+1)} · ${z.sent?'ارسال شده':'ارسال نشده'}</span>`).join('')}<button class="tch nw" data-act="mvGo" data-s="${x.id}" data-p="new">+ مرحله جدید</button></div>`:''}</div>`}).join('')}</div>`:'<div class="xnone">منبع دیگری نیست.</div>'}${can('src')?`<button class="acrow mvnew" data-act="mvNew"><span class="bkb lg" style="--bc:var(--blu)">+</span><span class="tx"><b>تعریف منبع جدید</b><small>حساب بانکی دیگری که از آن برداشت می‌شود</small></span></button>`:''}${one&&p&&one.id===famRoot(one)&&unallocCan(one)?`<button class="acrow mvun mvdel mvend" data-act="entUnalloc" data-id="${one.id}"><span class="bkb lg mvuni">${ic('x')}</span><span class="tx"><b>حذف تخصیص</b><small>${p.sent?'از پیگیری بیرون می‌آید و ':''}دوباره بدون بانک می‌شود</small></span>${ic('back').replace('class="i"','class="i flip"')}</button>`:''}`)}
ACT.entMove=d=>{const x=validated().find(r=>String(r.id)===String(d.id));if(!x)return;if(x.full){toast('این واریزی کامل با مشتری تسویه شده است',true);return}ldKey=PD(x);
  const own=parts().find(z=>z.ids.some(i=>String(i)===String(x.id)));if(own)partId=own.id;
  if(x.sentBid&&!own){const q=entBI(x);if(!q||q.b.closed){toast('لیست این واریزی بایگانی شده است',true);return}}
  else if(x.level===2&&!own){toast('اول خطای این واریزی را اصلاح کنید',true);return}
   
  if(!x.sentBid&&x.level<2&&pxUni(x))return;
  moveSheet([x.id],fullName(x)+'، '+fmt(x.amount)+' تومان',own)};
