ACT.stlSave=async()=>{stlRead();const x=entRow(),e=x&&entries.find(z=>z.id===x.id);if(!e)return;const o0=stl.i!=null?(e.settles||[])[stl.i]:null,own0=o0?+o0.amount||0:0;const name=clean(stl.name||stl.q||'');if(!name){toast('پرداخت‌کننده را انتخاب یا نامش را بنویسید',true);return}const a=+stl.amount||0;if(!a){toast('مبلغ را وارد کنید',true);return}
   
  if(a>own0+stlRoom(e)){toast(stlBkLock(e)?STLLK:'جمع تسویه‌ها از مبلغ کل این واریزی بیشتر می‌شود',true);return}
  if(a<own0&&depBkFix(e)&&!remCan()){toast(REMNO,true);return}
  const S=e.settles=(e.settles||[]).slice();
  const now=new Date().toISOString(),old=stl.i!=null?S[stl.i]:null,z={...(old||{}),st:old?(old.st||'ok'):'wait',id:(old&&old.id)||nid++,name,phone:stl.phone||'',inv:stl.inv||'',amount:a,tn:stl.tn||'',note:stl.note||'',cuId:stl.cuId||'',date:(old&&old.date)||todayISO(),at:now,by:who()};
  if(stl.imgD){const k=newImgKey('stl:'+z.id);if(await imgPut(k,stl.imgD)){z.imgs=stImgs(z).concat([k]);z.img=z.imgs[0]}else toast('حافظه پر است؛ عکس ذخیره نشد',true)}
  if(old&&old.cuId&&old.txId){const oc=custs.find(c=>String(c.id)===String(old.cuId)),ot=oc&&(oc.txs||[]).find(t=>t.id===old.txId);if(ot){ot.del=true;oc.lastAt=now}}
  delete z.txId;if(z.cuId&&z.st!=='wait'&&!z.byInv){const c=custs.find(q=>String(q.id)===String(z.cuId));if(c){const t={id:nid++,type:'pin',kind:'',weight:0,ppg:0,amount:a,note:'تسویه واریزی «'+fullName(e)+'»'+(z.inv?' · فاکتور '+z.inv:'')+(z.tn?' · پیگیری '+z.tn:''),date:todayISO(),at:now,by:who(),entId:e.id,stlId:z.id,img:z.img||''};(c.txs=c.txs||[]).push(t);c.lastAt=now;z.txId=t.id;saveCu()}}
  if(old)S[stl.i]=z;else S.push(z);e.updatedAt=now;e.updatedBy=who();saveE();const rm=stlSync(e);logA('edit','تسویه از مشتری',fullName(e)+' ← '+name+' | '+fmt(a)+' تومان'+(rm>0?' | مانده '+fmt(rm):''));stl=null;closeSheet();const v=$('view'),y=v.scrollTop;render();v.scrollTop=y;const r=entRow();toast(rm>0?remMsg(rm):z.st==='wait'?'ثبت شد · از مانده کم شد، در انتظار تأیید':r&&r.full?'تسویه کامل شد ✓':'ثبت شد · مانده بانکی '+fmt(r?r.amount:0)+' تومان')};
const remMsg=d=>fmt(d)+' تومان «مانده» شد · بانکش را از همین صفحه یا لیست واریز انتخاب کنید';
ACT.stlDel=()=>{const x=entRow(),e=x&&entries.find(z=>z.id===x.id);if(!e||stl.i==null)return;if(depBkFix(e)&&!remCan()){toast(REMNO,true);return}askConfirm(depBkFix(e)?'این تسویه حذف شود؟ مبلغش «مانده» می‌شود (واریز بانکیِ ثبت‌شده عوض نمی‌شود) و بانکش را خودتان انتخاب می‌کنید.':'این تسویه حذف شود؟ مبلغ دوباره به مانده بانکی برمی‌گردد.','حذف',()=>{const S=e.settles=(e.settles||[]).slice(),old=S[stl.i];stlDocOff(old);if(old&&old.cuId&&old.txId){const oc=custs.find(c=>String(c.id)===String(old.cuId)),ot=oc&&(oc.txs||[]).find(t=>t.id===old.txId);if(ot){ot.del=true;oc.lastAt=new Date().toISOString();saveCu()}}S.splice(stl.i,1);e.updatedAt=new Date().toISOString();saveE();const rm=stlSync(e);stl=null;closeSheet();render();toast(rm>0?'تسویه حذف شد · '+remMsg(rm):'تسویه حذف شد')})};
