function galCtx(){if(!GAL)return null; 
  if(GAL.k==='row'){const x=typeof phT==='function'&&phT();if(!x)return null;return{keys:xrPh(x),ed:true,pre:'xr',set:K=>{x.imgs=K;x.img=K[0]||'';if(!GAL.ck)svKeep()},meta:{name:phName(x),holder:phName(x),amount:phAmt(x),tn:x.tn||'',src:'',date:sv.date,kind:phRc(x)?'rc':'row'}}}
  if(GAL.k==='view')return{keys:(GAL.keys||[]).slice(),ed:false,pre:'xr',set:()=>{},meta:{name:GAL.name||'عکس کالا',holder:GAL.name||'',amount:0,tn:'',src:'',date:'',kind:'row'}};const e=entries.find(z=>String(z.id)===String(GAL.eid));if(!e)return null;const now=()=>new Date().toISOString();
  if(GAL.k==='it'){const q=entBI(e);if(!q)return null; 
    return{keys:itImgs(q.b,q.it),ed:can('track'),pre:'rc:'+e.id,
    set:K=>{q.it.imgs=K;q.it.img=K.length>0;q.it.at=now();saveB()},
    meta:{name:fullName(e),holder:e.holder||fullName(e),amount:q.it.amount,tn:q.it.tn||'',src:q.it.src||'',date:PD(e),kind:'bank'}}}
  const z=(e.settles||[]).find(s=>String(s.id)===String(GAL.sid));if(!z)return null;
  return{keys:stImgs(z),ed:can('edit'),pre:'stl:'+z.id,
    set:K=>{z.imgs=K;z.img=K[0]||'';e.updatedAt=now();e.updatedBy=who();saveE();stlSync(e);depImgSync(z,K)},
    meta:{name:fullName(e)+' (از '+z.name+')',holder:e.holder||fullName(e),payer:z.name,amount:z.amount,tn:z.tn||'',date:z.date,kind:'cust'}}}


