  const depth=el=>{const r=el.getBoundingClientRect(),w=r.width,h=r.height;if(!w||!h)return 1;
    if(w>=300||h>=110)return .978;if(w>=200)return .968;if(w>=110)return .955;return .9};
   
  const mode=el=>RMq.matches?'dim':SC?'scale':getComputedStyle(el).transform==='none'?'tf':'dim';
  const kf=(m,v,b)=>m==='scale'?{scale:String(v),filter:`brightness(${b})`}:m==='tf'?{transform:`scale(${v})`,filter:`brightness(${b})`}:{filter:`brightness(${b})`};
  const down=el=>{const m=mode(el),s=depth(el);el._pa&&el._pa.cancel();
    el._pa=el.animate([kf(m,1,1),kf(m,s,.93)],{duration:110,easing:'cubic-bezier(.3,.7,.4,1)',fill:'forwards'});el._ps=s;el._pm=m};
  const up=el=>{if(!el||!el._pa)return;const s=el._ps||.96,m=el._pm||'dim',a=el._pa;el._pa=null;
    const wait=Math.max(0,90-(performance.now()-t0)); 
    setTimeout(()=>{try{a.cancel()}catch(_){}
      if(!el.isConnected)return;el.animate(m==='dim'?[kf(m,1,.93),kf(m,1,1)]:[kf(m,s,.93),kf(m,1.012,1),kf(m,1,1)],{duration:m==='dim'?220:420,easing:'cubic-bezier(.32,.72,0,1)'})},wait)};
  document.addEventListener('pointerdown',e=>{if(e.button>0)return;const el=target(e);if(!el)return;cur=el;x0=e.clientX;y0=e.clientY;t0=performance.now();down(el)},{passive:true,capture:true});
  const end=()=>{if(cur){up(cur);cur=null}};
   
