document.addEventListener('click',e=>{const b=e.target&&e.target.closest&&e.target.closest('.ptm-keys [data-ck]');if(!b)return;e.preventDefault();e.stopPropagation();if(Date.now()-CKPD>700&&CK)ACT.ckK({k:b.dataset.k})},true);
