const wdPendTg=c=>{if(!c)return 0;const t=typeof ckTg==='function'?ckTg():'f',own=sv&&sv.edit?wdPend(c,sv.edit.no):0;return t==='d'?own:t==='p'?Math.max(0,wdPend(c)-own):wdPend(c)};
