  const t=D.t,pure=t.auto==='dep'&&String(t.entId)===String(e.id)&&!(t.items||[]).length&&(t.xr||[]).every(x=>x.t==='buy'),base=depBuyOf(e,D)||Math.round(+e.wd.amt||+e.amount||0),want=Math.max(0,base+d);
