const mgCu=e=>e&&(e.cuId!=null&&e.cuId!==''?e.cuId:e.wd&&e.wd.cu!=null?e.wd.cu:null);
const mgSent=e=>{let F;try{F=famOf(e)}catch(_){F=[e]}if(!F.length)F=[e];return !!e.sentBid||F.some(p=>p.sentBid||entBI(p))};
const mgStl=e=>(e.settles||[]).filter(z=>+z.amount>0);
 
function mgOk(e){if(!e||e.del||!entries.includes(e)||e.splitOf||mgSent(e))return false;let F;try{F=famOf(e)}catch(_){F=[e]}if(F.length>1)return false;
  if(e.wd){const D=depDoc(e);if(!D||D.t.auto!=='dep'||String(D.t.entId)!==String(e.id))return false} 
  return true}
function mgSame(a,b){const ca=mgCu(a),cb=mgCu(b);if(ca!=null&&cb!=null)return String(ca)===String(cb);
  return !!a.iban&&a.iban===b.iban&&nzName(stripName(a.name||''))===nzName(stripName(b.name||''))}
const mgIbanFit=(a,b)=>!a.iban||!b.iban||a.iban===b.iban;
 
function mgFind(o,skip){return entries.filter(t=>t!==skip&&t.id!==o.id&&(t.payDate||'')===(o.payDate||'')&&mgSame(t,o)&&mgIbanFit(t,o)&&mgOk(t)).sort((a,b)=>a.id-b.id)[0]||null}
 
function mgItems(p){const I=(p.items||[]).filter(z=>+z.amt);if(I.length&&Math.round(I.reduce((s,z)=>s+(+z.amt||0),0))===Math.round(+p.amount||0))return I.map(z=>({...z}));
  return [{k:'طلا',q:String(p.weight||''),amt:Math.round(+p.amount||0)}]}
const mgPart=e=>({sno:e.sno||'',code:toEn(e.code||'').trim(),amount:Math.round(+e.amount||0),weight:toEn(String(e.weight||'')),ppg:+e.ppg||0,items:mgItems(e),at:e.createdAt||e.updatedAt||e.entryDate||'',by:e.createdBy||'',eid:e.id});
const mgW=v=>parseFloat(toEn(String(v||'')))||0;
const mgSnap=t=>JSON.parse(JSON.stringify({amount:t.amount,code:t.code||'',weight:t.weight||'',ppg:t.ppg||0,items:t.items||null,buys:t.buys||null,iban:t.iban||'',card:t.card||'',holder:t.holder||'',bank:t.bank||''}));
 
function mgApply(t,p,o){o=o||{};const a0=+t.amount||0;if(!Array.isArray(t.buys)||!t.buys.length)t.buys=[mgPart(t)];t.buys.push(p);const B=t.buys;
  t.amount=B.reduce((s,b)=>s+(+b.amount||0),0);t.items=B.flatMap(b=>b.items.map(z=>({...z})));
  const w=Math.round(B.reduce((s,b)=>s+mgW(b.weight),0)*1000)/1000;t.weight=w?String(w):'';
  const ga=t.items.filter(z=>z.k==='طلا').reduce((s,z)=>s+(+z.amt||0),0);t.ppg=ppgOf(ga,t.weight)||0;
  t.code=[...new Set(B.map(b=>b.code).filter(Boolean))].join('، ');
  if(!t.iban&&o.iban){t.iban=o.iban;t.bank=''}if(!t.card&&o.card)t.card=o.card;if(!t.holder&&o.holder)t.holder=o.holder;
  t.updatedBy=who();t.updatedAt=new Date().toISOString();saveE();if(t.wd)depDocFix(t,(+t.amount||0)-a0);alloc=null}
 
function mgBuy(ne,cuId,S){if(!can('edit'))return null;let c=null;try{c=cuFindBy({cuId,name:ne.name,phone:ne.phone,nid:ne.nid})}catch(_){}
  const t=mgFind({...ne,cuId:c?c.id:cuId});if(!t)return null;
  const snap=mgSnap(t),s0=new Set((t.settles||[]).map(z=>String(z.id)));
  mgApply(t,mgPart({...ne,createdAt:ne.updatedAt}),{iban:ne.iban,card:ne.card,holder:ne.holder});
  for(const s of S||[]){try{const pc=pyOf({cuId:s.cuId,name:s.name,phone:s.phone});payDocMake(t,pc,+s.amount,{tn:s.tn||'',note:s.note||'',imgs:stImgs(s),st:s.st||'wait'})}catch(_){toast('تسویه «'+(s.name||'')+'» به سند وصل نشد',true)}}
  const add=(t.settles||[]).filter(z=>!s0.has(String(z.id))).map(z=>z.id);
  logA('merge','خرید به واریزی قبلی اضافه شد',stripName(t.name)+' | +'+fmt(ne.amount)+' تومان | جمع '+fmt(t.amount)+' تومان | واریز '+dates(t.payDate).fa,{ids:[t.id],mg:{t:t.id,snap,stl:add,auto:1}});
  return t}
 
function mgPeer(e){if(!e||!mgOk(e))return null;return entries.filter(t=>t!==e&&(t.payDate||'')===(e.payDate||'')&&mgSame(t,e)&&mgIbanFit(t,e)&&mgOk(t)).sort((a,b)=>a.id-b.id)[0]||null}
function mgPeerHTML(x){if(!can('edit')||!can('del'))return '';const e=entries.find(z=>z.id===x.id),p=mgPeer(e);if(!p)return '';
  return `<button type="button" class="mgj" data-act="mgJoin" data-a="${e.id}" data-b="${p.id}"><span class="mgi">${ic('split')}</span><span class="tx"><b>واریزی دیگر همین مشتری در این لیست</b><small>${fmt(p.amount)} تومان${p.code?' · فاکتور '+esc(toEn(p.code)):''}</small></span><span class="mgg">یکی کردن</span></button>`}
ACT.mgJoin=d=>{const a=entries.find(z=>String(z.id)===String(d.a)),b=entries.find(z=>String(z.id)===String(d.b));if(!a||!b||!mgOk(a)||!mgOk(b)||!mgSame(a,b)){toast('این دو واریزی دیگر یکی‌شدنی نیستند',true);render();return}
  if(mgStl(a).length&&mgStl(b).length){toast('هر دو واریزی تسویه از مشتری دارند؛ یکی کردن خودکار ممکن نیست',true);return}
   
  const [t,s]=mgStl(b).length||(!mgStl(a).length&&b.id<a.id)?[b,a]:[a,b];
  askConfirm(`دو واریزی «${stripName(t.name)}» یکی شود؟ جمع ${fmt((+t.amount||0)+(+s.amount||0))} تومان`,'یکی شود',()=>{
    if(!mgOk(t)||!mgOk(s)){toast('یکی از واریزی‌ها همین حالا عوض شد؛ دوباره امتحان کنید',true);render();return}
    const snap=mgSnap(t),p=mgPart(s);trashIds([s.id],'یکی شد با واریزی '+stripName(t.name));mgApply(t,p,{iban:s.iban,card:s.card,holder:s.holder});
    logA('merge','دو واریزی یکی شد',stripName(t.name)+' | '+fmt(snap.amount)+' + '+fmt(p.amount)+' = '+fmt(t.amount)+' تومان | واریز '+dates(t.payDate).fa,{ids:[t.id],mg:{t:t.id,snap,abs:s.id}});
    if(String(entId)===String(s.id))entId=t.id;render();toast('یکی شد — '+fmt(t.amount)+' تومان')})};
 
function mgUndo(x){const m=x.mg||{},t=entries.find(z=>String(z.id)===String(m.t));if(!t){toast('این واریزی دیگر در لیست نیست',true);return false}
  if(mgSent(t)){toast('این واریزی به بانک رفته؛ برگرداندن ممکن نیست',true);return false}
  const add=new Set((m.stl||[]).map(String));(t.settles||[]).filter(z=>add.has(String(z.id))).forEach(z=>{try{stlDocOff(z)}catch(_){}});t.settles=(t.settles||[]).filter(z=>!add.has(String(z.id)));
  const S=m.snap||{},a0=+t.amount||0;['amount','code','weight','ppg','iban','card','holder','bank'].forEach(k=>{if(k in S)t[k]=S[k]});if(S.items)t.items=S.items;else delete t.items;if(S.buys)t.buys=S.buys;else delete t.buys;
  t.updatedBy=who();t.updatedAt=new Date().toISOString();const a1=+t.amount||0;try{stlSync(t)}catch(_){}saveE();if(t.wd)depDocFix(t,a1-a0);if(m.abs!=null)restoreIds([m.abs]);alloc=null;return true}
 
function mgBuysHTML(x){const e=entries.find(z=>z.id===x.id)||x,B=e.buys;if(!Array.isArray(B)||B.length<2)return '';
  return `<div class="esec mgb"><b>خریدهای این واریزی</b><small class="emeta">${toFa(B.length)} خرید · جمع ${fmt(B.reduce((s,b)=>s+(+b.amount||0),0))} تومان</small><div class="mgl">${B.map((b,i)=>{const w=mgW(b.weight),pg=b.ppg||ppgOf(b.items.filter(z=>z.k==='طلا').reduce((s,z)=>s+(+z.amt||0),0),b.weight),at=b.at?new Date(b.at):null;
    return `<div class="mgr"><span class="mgn">${toFa(i+1)}</span><span class="tx"><b>${b.code?'فاکتور <span class="ltr">'+esc(b.code)+'</span>':'خرید '+toFa(i+1)}${b.sno?' <em class="snoT">#'+toFa(b.sno)+'</em>':''}</b><small>${[w?toFa(String(w))+' گرم':'',pg?'هر گرم '+fmt(pg):'',at&&!isNaN(at)?(d=>(d===todayISO()?'':dates(d).fa+' ')+toFa(at.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tehran'})))(at.toLocaleDateString('en-CA',{timeZone:'Asia/Tehran'})):'',b.by||''].filter(Boolean).map(esc).join(' · ')}</small></span><b class="am">${fmt(b.amount)} <i>تومان</i></b></div>`}).join('')}</div></div>`}


let posAutoBusy=0;


const posSetAt=d=>{const t=new Date(d+'T00:00:00');t.setDate(t.getDate()+1);return t.toISOString()};
function posAuto(){if(posAutoBusy||!TOKEN||(typeof can==='function'&&!can('src')))return;posAutoBusy=1;try{
  const t=todayISO(),now=ns();let chC=0,chS=0;
  for(const c of CH('pos')){const s=chSrc(c);if(!s)continue;
     
    const A=(c.txs||[]).filter(x=>!x.del&&x.auto&&x.type==='tout').sort((a,b)=>a.id-b.id),seen=new Map();
    A.forEach(x=>{const k=x.auto+'|'+x.srcId;if(!seen.has(k)){seen.set(k,x);return}x.del=true;x.delAt=now;chC=1;
      const S=sources.find(z=>String(z.id)===String(x.srcId)),L=S&&(S.led||[]).find(z=>String(z.id)===String(x.ledId));if(L&&!L.del){L.del=true;S.updatedAt=now;chS=1}});
     
    const day={};let man=0;
    chMoves(c).forEach(m=>{if(m.own){const x=(c.txs||[]).find(z=>z.id===m.own);if(x&&!x.auto)man-=m.a;return}if(String(m.d||'')<t)day[m.d]=(day[m.d]||0)+m.a});
    Object.keys(day).sort().forEach(d=>{let need=Math.round(day[d]);const use=Math.min(Math.max(0,man),Math.max(0,need));man-=use;need-=use;
      let T=(c.txs||[]).find(x=>!x.del&&x.type==='tout'&&x.auto===d),L=T&&(T.srcId!=null?sources.find(z=>String(z.id)===String(T.srcId)):null),LR=L&&(L.led||[]).find(z=>String(z.id)===String(T.ledId)&&!z.del);
      if(T){if(Math.round(+T.amount||0)===need)return;if(need<=0){T.del=true;T.delAt=now;if(LR){LR.del=true;L.updatedAt=now;chS=1}}else{T.amount=need;if(LR){LR.amount=need;L.updatedAt=now;chS=1}}chC=1;return}
      if(need<=0)return;const at=posSetAt(d);
      T={id:nid++,type:'tout',amount:need,srcId:s.id,date:t,at,by:'خودکار',auto:d};
      const R={id:nid++,type:'pos',amount:need,note:'کارتخوان «'+c.name+'» · فروش '+dates(d).fa,chId:c.id,chTx:T.id,auto:d,date:t,at,by:'خودکار'};T.ledId=R.id;
      (c.txs=c.txs||[]).push(T);(s.led=s.led||[]).push(R);s.updatedAt=now;chC=chS=1;
      try{logA('src','تسویه خودکار کارتخوان',c.name+' ← '+s.name+' | '+dates(d).fa+' | '+fmt(need)+' تومان')}catch(e){}})}
  if(chC)saveCu();if(chS)saveS()}catch(e){console.warn('posAuto',e)}finally{posAutoBusy=0}}


const bxIoHTML=s=>can('src')?`<div class="bxio"><button class="bxiob in" data-act="bxIO" data-id="${s.id}" data-d="in"><span class="bxioi">${ic('down')}</span><span><b>واریز به حساب</b><small>دریافت از مشتری یا واریز دستی</small></span></button><button class="bxiob out" data-act="bxIO" data-id="${s.id}" data-d="out"><span class="bxioi">${ic('share')}</span><span><b>برداشت از حساب</b><small>حواله به مشتری یا برداشت دستی</small></span></button></div>`:'';
ACT.bxIO=d=>{const s=sources.find(x=>String(x.id)===String(d.id));if(!s)return;const i=d.d==='in',bk=acBank(s);
  sheet(`<div class="sh-h"><div><b>${i?'واریز به':'برداشت از'} «${esc(s.name)}»</b><small class="shsub">${bk?'بانک '+esc(bk)+' · ':''}${esc(bkSub(s))}</small></div><button class="x" data-act="close" aria-label="بستن">×</button></div>
  <div class="bxioL">${can('debt')?`<button class="bxioR" data-act="bxDoc" data-id="${s.id}" data-d="${d.d}"><span class="bxioi ${i?'in':'out'}">${ic('edit')}</span><span class="tx"><b>${i?'دریافت از مشتری':'حواله به مشتری'}</b><small>سند مشتری باز می‌شود؛ ${i?'مانده مشتری کم و این حساب زیاد':'طلب مشتری کم و از این حساب کم'} می‌شود</small></span>${ic('back').replace('class="i"','class="i flip"')}</button>`:''}
  <button class="bxioR" data-act="acLedNew" data-id="${s.id}" data-t="${d.d}"><span class="bxioi g">${ic(i?'plus':'share')}</span><span class="tx"><b>${i?'سند واریز دستی':'سند برداشت دستی'}</b><small>سند شماره‌دار بدون حساب مشتری؛ فقط مانده همین حساب عوض می‌شود</small></span>${ic('back').replace('class="i"','class="i flip"')}</button></div>`)};
ACT.bxDoc=d=>{const s=sources.find(x=>String(x.id)===String(d.id));if(!s)return;ACT.svNew({pre:d.d==='out'?'hout':'hin',src:s.id})};
 
const svBkRows=q0=>{const q=clean(q0||'');if(!q||q.length<2||!can('src'))return '';const L=ownL().filter(s=>bkHit(s,q)).slice(0,3);
  return L.length?`<div class="cblh">حساب بانک مغازه<small>طرف سند نمی‌شود؛ ردیف حواله روی آن می‌نشیند</small></div>${L.map(s=>{const bk=acBank(s);return cbRow('svBk',{id:s.id},bk?bankBadge(bk):ic('bank'),esc(s.name),esc(bkSub(s)),'','bk')}).join('')}`:''};
ACT.svBk=d=>{const s=sources.find(x=>String(x.id)===String(d.id));if(!s||!sv)return;const p0=sv.qa&&sv.qa.p;
  sv.qa={...qaBlank(),p:p0&&p0.m!=='disc'&&p0.m!=='gold'?{...p0,m:'hav',srcId:s.id,chId:''}:pyNew('hav',{dir:'in',srcId:s.id})};sv.q='';svQO=0;svKeep();render();
  toast('ردیف حواله روی «'+s.name+'» آماده شد'+(svCu()?'':'؛ حالا مشتری سند را انتخاب کنید'));setTimeout(()=>{const q=$('svQ');if(q&&!svCu())q.focus({preventScroll:true})},80)};


const bxLiveT=c=>(c.txs||[]).filter(t=>!t.del);
const bxEnt=p=>entries.find(e=>!e.del&&String(e.id)===String(p.entId));
 
function bxWhy(t,p){if(p.m==='cust')return p.cuId&&custs.some(y=>!y.del&&String(y.id)===String(p.cuId))?'':'حساب مشتری طرف حواله پیدا نشد';
  if(p.m==='dep'){const e=bxEnt(p);if(!e)return 'واریزی این حواله پیدا نشد';const z=(e.settles||[]).find(q=>q.id===p.stlId);if(!z)return 'تسویه این حواله روی واریزی پیدا نشد';
    if(e.sentBid||entries.some(q=>!q.del&&q.splitOf===e.id)||e.splitOf!=null)return 'بخشی از این واریزی از بانک ارسال شده یا چند بخشی است';
    const st=(e.settles||[]).reduce((a,q)=>a+(+q.amount||0),0);if(Math.round((+e.amount||0)-st)>0)return 'این واریزی مانده بانکی جدا دارد';return ''}
  return 'این نوع ردیف خودکار منتقل نمی‌شود'}
function bxTxWhy(t){if(t.type!=='inv')return 'این ردیف سند نیست';if((t.items||[]).length||(t.xr||[]).length||+t.disc||t.gc)return 'سند کالا یا طلا دارد';if(!(t.pays||[]).length)return 'سند ردیف پرداخت ندارد';
  for(const p of t.pays){const w=bxWhy(t,p);if(w)return w}return ''}
const bxConvOk=c=>!!c&&!c.sys&&can('src')&&can('debt')&&bxLiveT(c).length>0&&bxLiveT(c).every(t=>!bxTxWhy(t));
const bxLike=c=>{const n=nzName(toEn(cuName(c)||c.name||''));return /بانک/.test(n)||ownL().some(s=>{const m=canon(s.name),k=canon(n);return m.length>2&&k.length>2&&(k.includes(m)||m.includes(k))})};
const bxGuessSrc=c=>{const L=ownL(),k=canon(c.name||'');return L.find(s=>canon(s.name)===k)||L.find(s=>{const m=canon(s.name);return m.length>2&&(k.includes(m)||m.includes(k))})||L.find(s=>{const b=canon(acBank(s));return b&&k.includes(b)})||null};
const bxConvHTML=c=>c&&!c.sys&&can('src')&&can('debt')&&bxLike(c)&&bxLiveT(c).length?`<button class="bxcv" data-act="bxConv" data-cu="${c.id}"><span class="bxioi">${ic('bank')}</span><span class="tx"><b>این حساب بانک مغازه است؟</b><small>${toFa(bxLiveT(c).length)} سند به حساب بانک منتقل می‌شود؛ مانده مشتری‌ها همان می‌ماند</small></span><em>انتقال</em></button>`:'';
let bxCv=null;
ACT.bxConv=d=>{const c=custs.find(x=>String(x.id)===String(d.cu));if(!c)return;if(!ownL().length){toast('اول حساب بانک مغازه را در صفحه بانک بسازید',true);return}
  const g=bxGuessSrc(c);bxCv={cu:c.id,src:bxCv&&String(bxCv.cu)===String(c.id)&&bxCv.src!=null?bxCv.src:g?g.id:null};bxConvDraw()};
function bxConvDraw(){const c=custs.find(x=>String(x.id)===String(bxCv.cu));if(!c)return;const T=bxLiveT(c),ok=bxConvOk(c),tot=T.reduce((a,t)=>a+(t.pays||[]).reduce((b,p)=>b+(+p.amount||0),0),0);
  const row=(t,p)=>{const w=bxWhy(t,p),e=p.m==='dep'?bxEnt(p):null,Y=p.m==='cust'?custs.find(y=>String(y.id)===String(p.cuId)):null,who=e?fullName(e):Y?cuName(Y):(p.entName||p.cuName||'');
    return `<div class="bxcvr${w?' no':''}"><span class="tx"><b>حواله به ${esc(who)}</b><small>سند ${toFa(t.no)} · ${esc(dates(t.date).fa)}${p.m==='dep'?' · واریزی، تأییدشده از همین بانک':''}${w?'<br><em>'+esc(w)+'</em>':''}</small></span><b class="r"><bdi dir="ltr">−${fmt(Math.abs(+p.amount||0))}</bdi> <i>تومان</i></b></div>`};
  sheet(`<div class="sh-h"><div><b>انتقال به حساب بانک</b><small class="shsub">حساب «${esc(cuName(c))}» حذف و سندهایش حواله از بانک می‌شوند</small></div><button class="x" data-act="close" aria-label="بستن">×</button></div>
  <div class="d6l"><small>کدام حساب بانک مغازه</small><div class="chps">${ownL().map(s=>{const bk=acBank(s);return `<button class="chp${String(bxCv.src)===String(s.id)?' on':''}" data-act="bxConvS" data-id="${s.id}">${bk?bankBadge(bk):ic('bank')}<span><b>${esc(s.name)}</b><small>${esc(bkSub(s))}</small></span></button>`}).join('')}</div></div>
  <div class="bxcvL">${T.map(t=>(t.pays||[]).length?(t.pays||[]).map(p=>row(t,p)).join(''):`<div class="bxcvr no"><span class="tx"><b>${esc(invTitle(t))}</b><small><em>${esc(bxTxWhy(t))}</em></small></span></div>`).join('')}</div>
  <small class="bxcvn">${ok?`بعد از انتقال ${fmt(Math.abs(tot))} تومان برداشت از این حساب بانک ثبت می‌شود و این «حساب مشتری» حذف می‌شود (با «بازگردانی» برمی‌گردد).`:'ردیف‌های قرمز خودکار منتقل نمی‌شوند؛ اول همان سندها را درست کنید.'}</small>
  <button class="xgo" data-act="bxConvGo"${bxCv.src==null||!ok?' disabled':''}>${ic('check')} انتقال به حساب بانک</button>`)}
ACT.bxConvS=d=>{if(!bxCv)return;bxCv.src=+d.id||d.id;bxConvDraw()};
 
function bxDepPaid(e,z,s,now){let b=batches.find(x=>x.date===PD(e)&&!x.closed);const nb=!b;if(nb){b={id:nid++,date:PD(e),pay:PD(e),createdAt:now,by:who(),items:[]};batches.unshift(b)}
  const K=stImgs(z),at=z.at||now,d=new Date(at),it={sAt:at,pay:PD(e),id:e.id,name:e.name,title:e.title||'',code:e.code||'',amount:+e.amount||0,total:+e.amount||0,settled:0,settles:[],iban:e.iban||'',bank:ibanBank(e.iban||'')||e.bank||'',src:s.name,st:'ok',tn:z.tn||'',time:isNaN(d)?'':p2(d.getHours())+':'+p2(d.getMinutes()),at:now,mvFrom:z.id,...(K.length?{imgs:K,img:K[0]}:{})};
  b.items.push(it);e.sentBid=b.id;return {b,it,nb}}
ACT.bxConvGo=()=>{if(!bxCv)return;const c=custs.find(x=>String(x.id)===String(bxCv.cu)),s=sources.find(x=>String(x.id)===String(bxCv.src));if(!c||!s||!bxConvOk(c)){toast('انتقال انجام نشد؛ ردیف‌های قرمز را ببینید',true);if(c&&bxCv)bxConvDraw();return}
  const now=ns(),at=new Date().toISOString(),U=[],names=[];
  for(const t of bxLiveT(c)){const P=t.pays.filter(p=>p.m==='cust'),Dp=t.pays.filter(p=>p.m==='dep'),G=new Map();let first=true;
    P.forEach(p=>{const k=String(p.cuId);if(!G.has(k))G.set(k,[]);G.get(k).push(p)});
    for(const [k,Q] of G){const Y=custs.find(y=>String(y.id)===k);
      const t2={id:nid++,type:'inv',no:first?t.no:invNext(),date:t.date,rate:t.rate||0,mz:t.mz||0,items:[],xr:[],tax:false,disc:0,sub:0,total:0,
        pays:Q.map(p=>{const q={m:'hav',srcId:s.id,amount:-(+p.amount||0),tn:p.tn||''};const K=xrPh(p);if(K.length){q.imgs=K.slice();q.img=K[0]}return q}),at:t.at,by:t.by,mv:{cu:c.id,tx:t.id,at:now,by:who()}};first=false;
      const X=Q.map(p=>(Y.txs||[]).find(x=>String(x.id)===String(p.xfId))).filter(x=>x&&!x.del);X.forEach(x=>{x.del=true;x.delAt=at;x.delBy=who()});
      (Y.txs=Y.txs||[]).push(t2);Y.lastAt=now;U.push({k:'cu',Y,t2,X});names.push(cuName(Y))}
    for(const p of Dp){const e=bxEnt(p),i=(e.settles||[]).findIndex(q=>q.id===p.stlId),z=e.settles[i];
      e.settles=e.settles.filter((_,j)=>j!==i);e.updatedAt=now;e.updatedBy=who();const R=bxDepPaid(e,z,s,now);stlSync(e);U.push({k:'dep',e,z,i,...R});names.push(fullName(e))}
    t.del=true;t.delAt=at;t.delBy=who();t.mvTo=s.id;U.push({k:'t',t})}
  c.del=true;c.delAt=at;saveE();saveB();saveCu();saveS();logA('cust','انتقال به حساب بانک',cuName(c)+' → '+s.name+' | '+names.join('، '));
  const cu=c.id;bxCv=null;closeSheet();ACT.acOpen({id:s.id});
  toast('حواله‌ها به «'+s.name+'» منتقل شد','', 'بازگردانی',()=>{const at2=new Date().toISOString();U.forEach(u=>{
    if(u.k==='cu'){u.t2.del=true;u.t2.delAt=at2;u.t2.delBy=who();u.X.forEach(x=>{x.del=false})}
    else if(u.k==='dep'){u.b.items=u.b.items.filter(x=>x!==u.it);if(u.nb&&!u.b.items.length)batches=batches.filter(x=>x!==u.b);delete u.e.sentBid;const S=u.e.settles||[];S.splice(Math.min(u.i,S.length),0,u.z);u.e.settles=S;stlSync(u.e)}
    else{u.t.del=false;delete u.t.mvTo}});
    const C=custs.find(x=>String(x.id)===String(cu));if(C)C.del=false;saveE();saveB();saveCu();saveS();render()})};


const isPy=c=>!!c&&c.sys==='py';
const pyNz=s=>String(s||'').replace(/ي/g,'ی').replace(/ك/g,'ک');
 
const pyBankSrc=name=>{const n=clean(pyNz(name));if(!n||!/بانک/.test(n)||!sources.length)return null;const k=canon(n);if(k.length<2)return null;
  const L=ownL();return L.find(s=>canon(s.name)===k)||L.find(s=>{const m=canon(s.name);return m.length>2&&(k.includes(m)||m.includes(k))})||null};
const pyFind=name=>{const k=nzName(stripName(name||''));return k?custs.find(c=>isPy(c)&&!c.del&&nzName(c.name)===k)||null:null};
function pyMake(o){const now=ns(),s=pyBankSrc(o.name),c={id:nid++,sys:'py',name:clean(stripName(o.name||'')),phone:phD(o.phone).length===11?phD(o.phone):'',txs:[],createdAt:now,lastAt:now,by:who()};
  if(s)c.src=s.id;custs.push(c);logA('cust','پرداخت‌کننده تسویه (بدون حساب مشتری)',cuName(c)+(s?' → حساب بانک «'+s.name+'»':''));return c}
 
function pyOf(o){if(o.cuId!=null&&o.cuId!==''){const c=custs.find(z=>!z.del&&String(z.id)===String(o.cuId)&&(!z.sys||isPy(z)));if(c)return c}
  if(pyBankSrc(o.name)){const p=pyFind(o.name);return p||pyMake(o)}
  return cuFindBy({name:o.name,phone:o.phone})||pyFind(o.name)||pyMake(o)}
 
const pyStlTx=t=>t&&(t.auto==='stl'||((t.type==='pin'||t.type==='pout')&&t.entId!=null));
function pyLike(c){if(!c||c.del||c.sys)return false;
  if(phD(c.phone).length||String(c.nid||'').trim()||(c.bk&&(c.bk.iban||c.bk.card))||clean(c.grp||'')||clean(c.note||'')||c.av||(c.idImgs||[]).length)return false;
  if(pyBankSrc(cuName(c)))return true;const T=c.txs||[];return T.length>0&&T.every(pyStlTx)}
let pyMigSig='';
function pyMig(){if(!can('debt'))return 0;const sig=custs.length+'|'+sources.length+'|'+custs.reduce((a,c)=>a+(c.txs||[]).length,0);if(sig===pyMigSig)return 0;pyMigSig=sig;
  let n=0;const now=ns(),names=[];for(const c of custs){if(!pyLike(c))continue;const s=pyBankSrc(cuName(c));c.sys='py';if(s)c.src=s.id;c.pyAt=now;c.lastAt=now;n++;names.push(cuName(c)+(s?' → «'+s.name+'»':''))}
  if(n){saveCu();logA('cust','حساب‌های پرداخت‌کننده تسویه از فهرست مشتریان برداشته شد',names.join('، '))}return n}
 
function pyMoves(s){const L=[];for(const c of custs){if(c.del||!isPy(c)||c.src==null||String(c.src)!==String(s.id))continue;
  for(const t of c.txs||[]){if(t.del||(s.balAt&&String(t.at||'')<s.balAt))continue;const a=-Math.round(txD(t).r||0);if(!a)continue;
    const p=(t.pays||[]).find(q=>q.m==='dep'),who=p&&p.entName?p.entName:(t.type==='inv'?invTitle(t):clean(t.note||''));
    L.push({at:t.at,date:t.date,a,cu:c.id,tx:t.id,t:(p?'تسویه واریزی ':a<0?'برداشت · ':'واریز · ')+who,sub:(t.type==='inv'?'سند '+toFa(t.no):'')+(p&&p.tn?' · پیگیری '+p.tn:''),K:p?(p.imgs&&p.imgs.length?p.imgs:p.img?[p.img]:[]):[]})}}return L}


let cuDt='',cuN=60;
 
const cuQDate=q=>/^\s*\d{1,2}\.\d{1,3}\s*$/.test(toEn(String(q||'')))?'':qDate(q);
const CUTX_NUM=/^(amount|total|sub|disc|w|weight|am|q|ppg|no|tn|rate|mz|card|iban)$/;
const CUTX_SKIP=/^(id|at|at0|by|date|type|dk|entId|stlId|peer|txId|cu|cuId|img|imgs|edOf|auto|src|pid|bid|sid|m|dir|xfId|del|draft)$/;
const cuTxTitle=t=>t.type==='inv'?invTitle(t):t.type==='xf'?(t.inv?'پرداخت فاکتور مشتری دیگر':'انتقال مانده'):t.type==='cv'?'تبدیل '+(t.dir==='g2r'?'طلایی به ریالی':'ریالی به طلایی'):((TXT[t.type]||{}).t||'سند');
 
function cuTxHay(t){const S=[cuTxTitle(t)],N=[];
  const walk=(o,k,d)=>{if(o==null||d>4)return;if(Array.isArray(o)){for(const x of o)walk(x,k,d+1);return}
    if(typeof o==='object'){for(const j in o)if(!CUTX_SKIP.test(j))walk(o[j],j,d+1);return}
    if(typeof o==='string'){S.push(o);N.push(o)}else if(typeof o==='number'&&CUTX_NUM.test(k))N.push(String(o))};
  walk(t,'',0);return {s:nzName(S.join(' ')),n:N}}
 
const cuTxHayC=t=>{const X=sxGet();let h=X.tx.get(t);if(!h){h=cuTxHay(t);h.d=h.n.map(z=>toEn(String(z||'')).replace(/\D/g,''));X.tx.set(t,h)}return h};
const cuTxHit=(t,q,dOk)=>{const h=cuTxHayC(t),qd=dOk?dOk.qd:null;return (q.length>=2&&h.s.includes(q))||(qd!=null?qd.length>=3&&h.d.some(z=>z.includes(qd)):!!dOk&&h.n.some(dOk))};
function cuTxHits(dq,q,dOk){if(!dq&&!q)return [];const R=[];
  for(const c of CU())for(const t of c.txs||[]){if(t.del||t.draft||!t.date)continue;if(dq&&t.date!==dq)continue;
    if(q&&!(cuTxHit(t,q,dOk)||(dq&&cuHit(c,q,dOk))))continue;R.push([c,t])}
  return R.sort((a,b)=>String(b[1].date+'|'+(b[1].at||'')).localeCompare(String(a[1].date+'|'+(a[1].at||''))))}
function cuTxRow(c,t){const d=txD(t),ks=[d.r?['r',d.r]:null,d.g?['g',d.g]:null,...Object.keys(d.x||{}).filter(k=>+d.x[k]).map(k=>[k,+d.x[k]])].filter(Boolean),[k,v]=ks[0]||['r',0];
  const ico=t.type==='inv'?'inv':t.type==='xf'?'swap':t.type==='cv'?'coin':((TXT[t.type]||{}).i||'plus');
  const sub=[cuName(c),t.type==='inv'?[...(t.items||[]).map(i=>i.k?i.k+dsP(i):''),...(t.xr||[]).filter(x=>dsOf(x)).map(x=>xrLab(x)+dsP(x))].filter(Boolean).join('، '):[t.kind,t.weight?wFmt(t.weight)+' گرم':''].filter(Boolean).join('، '),t.note].filter(Boolean).join(' · ');
  return `<button class="c6r" data-act="cuTxGo" data-cu="${c.id}" data-tx="${t.id}"><span class="c6a iv">${ic(ico)}</span><span class="tx"><b>${esc(cuTxTitle(t))}</b><small>${esc(sub)}</small></span><span class="c6ivv${v<0?' d':v>0?' c':''}"><b>${v?balV(k,v):'تسویه'}</b><small>${v?esc(balU(k))+(ks.length>1?' +'+toFa(ks.length-1):''):''}</small></span></button>`}
 
function cuTxHTML(TX){if(!TX.length)return '';const N=liteCap(TX.length,cuN,8),L=TX.slice(0,N),cnt={};TX.forEach(([,t])=>cnt[t.date]=(cnt[t.date]||0)+1);let h='',last=null;
  for(const [c,t] of L){if(t.date!==last){if(last!==null)h+='</div>';last=t.date;const r=relDay(last);h+=`<div class="fday sticky hit cutxd"><span>${['امروز','دیروز','فردا'].includes(r)?r+'، ':''}${esc(dates(last).wd+' '+dates(last).fa)}</span><small>${fmt(cnt[last])} ردیف</small></div><div class="c6l c6tx">`}h+=cuTxRow(c,t)}
  if(last!==null)h+='</div>';
  return `${cuDt||cuQDate(cuQ)?'':`<div class="c6gh">در گردش حساب‌ها · ${fmt(TX.length)} ردیف</div>`}${h}${TX.length>N?`<button class="btn sec cutxm" data-act="cuTxMore">نمایش بیشتر (${fmt(TX.length-N)} ردیف دیگر)</button>`:''}`}
const cuDtChip=qd=>cuDt?`<div class="fdate">${ic('cal')} ${esc(relDay(cuDt))}، ${esc(dates(cuDt).fa)}<button data-act="cuDtClr" aria-label="حذف">×</button></div>`:qd?`<div class="fdate">${ic('cal')} سندهای ${esc(dates(qd).fa)}</div>`:'';
const cuReList=()=>{const r=$('cures');if(r)srchSwap(r,cuListHTML())};
ACT.cuCal=()=>{const M=new Set();for(const c of CU())for(const t of c.txs||[])if(!t.del&&!t.draft&&t.date)M.add(t.date);
  openCal(cuDt||todayISO(),iso=>{cuDt=iso;cuN=60;render();$('view').scrollTop=0},{title:'جستجوی تاریخ',sub:'روزهای نقطه‌دار سند دارند',q:[[-2,'پریروز'],[-1,'دیروز'],[0,'امروز']],marks:M})};
ACT.cuDtClr=()=>{cuDt='';cuN=60;render()};
