  const R=[...(x.undone?[]:dn?[['tlUn','لغو تأیید','undo','#6b7385']]:[['tlChk','وارد شد','check','#178049']]),...A.R.filter(a=>canAct(a[0]))],L=[['tlOpen','سند','inv','#3b6fd6'],...A.L.filter(a=>canAct(a[0]))];
