const bkSF=s=>{if(BKS.sid!==String(s.id))BKS={sid:String(s.id),q:'',f:'',t:''};return BKS};
const bkRowTx=r=>{const d=document.createElement('div');d.innerHTML=r.h||'';const b=d.querySelector('.tx b'),sm=d.querySelector('.tx small'),v=d.querySelector('.txv small');return {t:b?b.textContent.replace(/^\s*خودکار\s*/,'').trim():'',s:sm?sm.textContent.trim():'',st:v?v.textContent.trim():'',auto:!!d.querySelector('.autg')}};
function bkFilt(s,R){const F=bkSF(s),q=nzName(toEn(clean(F.q||'')));if(!q&&!F.f&&!F.t)return R;
  return R.filter(r=>{if(r.f==='mark')return !q;const d=r.d||'';if(F.f&&d&&d<F.f)return false;if(F.t&&d&&d>F.t)return false;if(!q)return true;const x=bkRowTx(r);return nzName(toEn(x.t+' '+x.s+' '+x.st+' '+String(Math.abs(r.a||0)))).includes(q)})}
function bkSLab(){const F=BKS;if(!F.f&&!F.t)return 'بازه';const o=stmQk().find(o=>o[2]===F.f&&o[3]===F.t);return o?o[1]:'بازه'}
function bkSBar(s){const F=bkSF(s),n=F.f||F.t;return `<div class="stmbar"><div class="fsearch stms2">${ic('search')}<input id="bkSQ" type="search" enterkeyhint="search" autocomplete="off" placeholder="جستجو در گردش حساب…" value="${esc(F.q)}">${F.q?`<button type="button" class="x" data-act="bkSQClr" aria-label="پاک کردن جستجو">×</button>`:''}<button type="button" class="cufbtn${n?' on':''}" data-act="bkSR" aria-label="بازه تاریخ">${ic('cal')}<span>${esc(bkSLab())}</span></button></div><button type="button" class="stme" data-act="bkPdf" aria-label="صورتحساب PDF">${ic('paste')}<span>PDF</span></button><button type="button" class="stme" data-act="bkXls" aria-label="صورتحساب Excel">${ic('list')}<span>Excel</span></button></div>`}
function bkSRe(bar){const s=curBk();if(!s||cur!=='bank')return;const L=$('acLW');if(L){const m=typeof flipSnap==='function'?flipSnap(L):null;L.innerHTML=acListHTML(s,acRows(s));if(m)flipPlay(L,m)}if(bar){const B=$('bkSB');if(B)B.innerHTML=bkSBar(s)}}
document.addEventListener('input',e=>{const I=e.target;if(!I||I.id!=='bkSQ')return;clearTimeout(I._t);I._t=setTimeout(()=>{BKS.q=I.value;bkSRe(false)},160)});
ACT.bkSQClr=()=>{BKS.q='';bkSRe(true)};
ACT.bkSR=(d,e)=>{const T=e&&e.target&&e.target.closest('.cufbtn');popMenu(T,stmQk().map(o=>['bkSRp',ic(o[2]===BKS.f&&o[3]===BKS.t?'check':'cal'),o[1],{k:o[0]}]))};
ACT.bkSRp=d=>{const o=stmQk().find(x=>x[0]===d.k);if(!o)return;BKS.f=o[2];BKS.t=o[3];bkSRe(true)};
function bkStRows(s){const R=bkFilt(s,acRows(s)).filter(r=>r.f!=='mark'&&!r.res);return R.slice().sort((a,b)=>String(a.d||'').localeCompare(String(b.d||''))||String(a.at||'').localeCompare(String(b.at||''))).map(r=>({...bkRowTx(r),d:r.d,a:+r.a||0,way:!!r.way,old:!!r.old}))}
const bkFile=s=>('گردش حساب '+s.name+' ('+(BKS.f||BKS.t?stmPer({F:BKS}):toFa(dates().fa))+')').replace(/[\\/:*?"<>|]/g,'-');
ACT.bkPdf=()=>{const s=curBk();if(!s)return;const L=bkStRows(s);if(!L.length){toast('ردیفی برای این جستجو نیست',true);return}openPrint(()=>bkPdfHTML(s,L))};
function bkPdfHTML(s,L){const m=acSum(s),bk=acBank(s),inn=L.filter(r=>r.a>0).reduce((t,r)=>t+r.a,0),out=L.filter(r=>r.a<0).reduce((t,r)=>t-r.a,0),per=BKS.f||BKS.t?stmPer({F:BKS}):'';
  const html=`<section class="pg">${pdfTop('گردش حساب بانک',dates())}<h1>${esc(s.name)}</h1><div class="sub">${bk?'<span class="rg">بانک '+esc(bk)+'</span>':''}${s.iban?'<span class="rg">شبا '+esc(toFa(s.iban))+'</span>':''}<span class="rg">${fmt(L.length)} ردیف</span>${per?'<span class="rg">'+esc(per)+'</span>':''}${BKS.q?'<span class="rg">جستجو: '+esc(BKS.q)+'</span>':''}</div>
  <div class="kcs"><div class="kc"><div class="kh">مانده نهایی</div><div class="kv"><bdi>${m.known?(m.fin<0?'−':'')+fmt(Math.abs(m.fin)):'—'}</bdi><u>تومان</u></div></div><div class="kc c"><div class="kh">جمع واریز این فهرست</div><div class="kv"><bdi>${fmt(inn)}</bdi><u>تومان</u></div></div><div class="kc d"><div class="kh">جمع برداشت این فهرست</div><div class="kv"><bdi>${fmt(out)}</bdi><u>تومان</u></div></div></div>
  <table class="bkt"><thead><tr><th>#</th><th>تاریخ</th><th class="ds">شرح</th><th>واریز</th><th>برداشت</th><th>وضعیت</th></tr></thead><tbody>${L.map((r,i)=>`<tr><td class="n">${fmt(i+1)}</td><td class="dt">${esc(dates(r.d).fa)}</td><td class="ds"><b>${esc(r.t)}</b>${r.auto?' <i class="ag">خودکار</i>':''}<span>${esc(r.s)}</span></td><td class="am bl">${r.a>0?fmt(r.a):'—'}</td><td class="am rd">${r.a<0?fmt(-r.a):'—'}</td><td class="st">${esc(r.st)}</td></tr>`).join('')}</tbody>
  <tfoot><tr><td colspan="3">جمع</td><td class="am bl">${fmt(inn)}</td><td class="am rd">${fmt(out)}</td><td></td></tr></tfoot></table>${pdfFoot()}</section>`;
   
  const css=`.kcs{display:grid;grid-template-columns:repeat(3,1fr);gap:1.6mm;margin:2mm 0 0}.kc{min-width:0;border:.15mm solid #a89a7c;border-top:.45mm solid #a87b1f;padding:1.2mm 2.6mm 1.4mm}.kh{font-size:6.6pt;font-weight:700;color:#5f4712}
  .kv{display:flex;align-items:baseline;gap:1.2mm}.kv bdi{font-size:13pt;font-weight:800;direction:ltr;unicode-bidi:isolate;line-height:1.35}.kc.c bdi{color:#1f3f8f}.kc.d bdi{color:#9b1c31}.kv u{font-size:6.8pt;color:#544c42;font-weight:500}
  table.bkt{width:100%;border-collapse:collapse;margin-top:3mm}.bkt th{text-align:center;padding:1.2mm 1mm}.bkt th.ds{text-align:right}.bkt td{font-size:7.6pt;padding:1.3mm 1mm;vertical-align:top}
  .bkt td.n{color:#544c42;text-align:center}.bkt td.dt{white-space:nowrap;color:#38322b}.bkt td.ds b{font-weight:700}.bkt td.ds span{display:block;color:#544c42;font-size:6.6pt}.bkt td.am{text-align:center;white-space:nowrap;font-weight:700;font-size:8pt}.bkt td.st{font-size:6.8pt;color:#38322b;text-align:center;border:0;border-bottom:.15mm solid #a89a7c;border-radius:0;background:none;display:table-cell}
  .rd{color:#9b1c31}.bl{color:#1f3f8f}.ag{font-size:5.8pt;font-weight:700;border:.15mm solid #9cc7b3;background:#eef7f2;color:#1d6b4a;border-radius:99px;padding:0 1.4mm}.bkt tfoot td{font-weight:700;background:#f4ecd8;border-top:.3mm solid #a87b1f;border-bottom:.2mm solid #2f2a24}
  .bkt thead{display:table-header-group}.bkt tr{break-inside:avoid}`;
  return pdfDoc(bkFile(s),html).replace(/@page\{size:A5 landscape;[^}]*\}/,'@page{size:A4;margin:10mm 10mm}').replace('</head>','<style>'+css+'</style></head>')}
ACT.bkXls=()=>{const s=curBk();if(!s)return;if(typeof XLSX==='undefined'){toast('برای Excel اینترنت لازم است',true);return}const L=bkStRows(s);if(!L.length){toast('ردیفی برای این جستجو نیست',true);return}
  const m=acSum(s),wb=XLSX.utils.book_new();wb.Workbook={Views:[{RTL:true}]};
  const info=[['گردش حساب بانک — مطلا'],['حساب',s.name],['بانک',acBank(s)||''],['شبا',s.iban||''],['تاریخ گزارش',dates().fa],BKS.f||BKS.t?['بازه',stmPer({F:BKS})]:[],BKS.q?['جستجو',BKS.q]:[],['مانده نهایی',m.known?m.fin:''],[]];
  const H=['ردیف','تاریخ','شرح','جزئیات','واریز (تومان)','برداشت (تومان)','وضعیت','نوع ثبت'];
  const a=[...info,H,...L.map((r,i)=>[i+1,dates(r.d).fa,r.t,r.s,r.a>0?r.a:'',r.a<0?-r.a:'',r.st,r.auto?'خودکار':'دستی'])];
  const w=XLSX.utils.aoa_to_sheet(a);w['!cols']=[{wch:6},{wch:14},{wch:28},{wch:40},{wch:16},{wch:16},{wch:14},{wch:10}];
  for(let r=info.length+2;r<=a.length;r++)['E','F'].forEach(col=>{const cl=w[col+r];if(cl&&typeof cl.v==='number')cl.z='#,##0'});
  XLSX.utils.book_append_sheet(wb,w,'گردش حساب');save(bkFile(s)+'.xlsx',XLSX.write(wb,{bookType:'xlsx',type:'array'}),'فایل Excel گردش حساب آماده شد')};


function lnkMirror(c,t,p,no,now){const Y=custs.find(z=>String(z.id)===String(p.cuId));if(!Y)return null;
  const x={id:nid++,type:'inv',dk:p.amount>0?'out':'in',no,date:t.date||sv.date,rate:0,mz:0,items:[],xr:[],tax:false,disc:0,sub:0,total:0,
    pays:[{m:'lnk',lm:p.m,amount:-(+p.amount||0),cuId:c.id,cuName:cuName(c),...(p.why?{why:p.why}:{}),...(p.tn?{tn:p.tn}:{}),...(p.wt?{wt:1}:{}),...(p.okAt?{okAt:p.okAt,okBy:p.okBy}:{})}],
    note:'',lk:{cu:c.id,tx:t.id},at:now,by:who(),cn:cnNext(Y)};
  (Y.txs=Y.txs||[]).push(x);Y.lastAt=now;return x}
const lnkLab=p=>{const out=pAmt(p)<0,bk=p.lm==='pos'?'کارتخوان':p.lm==='hav'?(out?'حواله به بانک':'حواله از بانک'):(out?'حواله به':'حواله از');return bk+' «'+(p.cuName||'')+'»'};
 
function lkGoTx(t,why){if(t.pd){toast('«کارتخوان روز» خودکار از کارتخوان سندهای همان روز ساخته می‌شود؛ '+why+' از خود سند مشتری (روی هر ردیف بزنید)',true);return}
  if(t.bl){toast('این سند از «لیست واریز» آمده؛ '+why+' از خود لیست واریز',true);ldKey=t.date;go('lday');return}
  const C=custs.find(z=>String(z.id)===String(t.lk.cu)),T=C&&(C.txs||[]).find(z=>String(z.id)===String(t.lk.tx)&&!z.del);
  toast('این سند طرف مقابل «'+(C?cuName(C):'')+'» است؛ '+why+' از سند اصلی',true);if(T)invOpen(C.id,T.id)}
 
const bkSrcOf=c=>c&&c.srcId!=null&&c.srcId!==''?sources.find(s=>String(s.id)===String(c.srcId))||null:null;


function bkLinkHTML(){return ''}


const bkSimNm=n=>canon(nzName(toEn(String(n||''))).replace(/(^|\s)بانک(?=\s|$)/g,' ').replace(/[()（）«»\-_،,.\u200c]/g,' ').replace(/\s+/g,''));
function bkAutoLink(c){if(!c||c.grp!=='بانک'||c.srcId!=null||c.srcNo)return 0;const M=ownL().filter(z=>bkSimNm(z.name)===bkSimNm(c.name)&&!bkCus().some(o=>o!==c&&String(o.srcId)===String(z.id)));if(M.length!==1)return 0;c.srcId=M[0].id;c.srcAt=c.srcAt||'';return 1}


const srcUsed=s=>batches.some(b=>(b.items||[]).some(x=>x.src===s.name))||Object.values(drafts||{}).some(L=>(L||[]).some(p=>p&&p.src&&String(p.src.id)===String(s.id)));
function bkSrcMake(c){const n0=cuName(c),nm=sources.some(z=>z.name===n0)?n0+' · '+toFa(c.cno||c.id):n0,so={id:nid++,name:nm,bank:bkOfCu(c)||'',limit:0,count:0,iban:c.iban||'',card:c.card||'',auto:1};if(ownSet())so.own=1;sources.push(so);return so}
function bkSrcFor(c){const so=c.srcId!=null?sources.find(z=>String(z.id)===String(c.srcId)&&!z.cash):null;if(so)return so;
  return ownL().find(z=>bkSimNm(z.name)===bkSimNm(c.name)&&!bkCus().some(o=>o!==c&&String(o.srcId)===String(z.id)))||null}
function bkSrcAll(){if(!can('src'))return 0;let n=0,ch=0;for(const c of bkCus()){if(c.srcNo||bkSrcOf(c))continue;let so=bkSrcFor(c);if(!so){so=bkSrcMake(c);n++}c.srcId=so.id;c.srcAt=c.srcAt||'';ch++}
  if(ch)audBg(()=>{if(n)saveS();saveCu()});return ch}
 
const srcLinkCands=()=>bkCus().filter(c=>{const s=bkSrcOf(c);return !s||(s.auto&&!srcUsed(s))});
function srcLinkDo(so,c){if(!c){const id=bkCuNew(so.name);c=custs.find(z=>String(z.id)===String(id))}if(!c)return null;
  const old=bkSrcOf(c);if(old&&old!==so&&old.auto&&!srcUsed(old)){sources=sources.filter(z=>z!==old);saveS()}
  c.srcId=so.id;c.srcAt=c.srcAt||'';delete c.srcNo;if(!c.bank&&so.bank)c.bank=so.bank;c.updatedAt=new Date().toISOString();bkDepSync(c,1);saveCu();logA('cust','اتصال منبع به حساب بانک',so.name+' ← '+cuName(c));return c}
const bkUniL=()=>DSRC().filter(s=>!srcBk(s));
const bkUniCard=()=>{if(!can('src')||cuQ)return '';const n=bkUniL().length;return n?`<button type="button" class="bkuni" data-act="bkUni"><span class="bkunii">${ic('bank')}</span><span class="tx"><b>${toFa(n)} منبع واریز هنوز حساب بانکی ندارد</b><small>بزنید و بگویید هر کدام کدام بانک است تا مانده‌اش در بانک‌ها بیاید</small></span>${ic('back').replace('class="i"','class="i flip"')}</button>`:''};
function bkUniHTML(){const L=bkUniL();return `<div class="sh-h"><div><b>منبع‌های بدون حساب بانکی</b><small class="shsub">هر منبع را به حساب بانکی خودش وصل کنید؛ لیست‌های واریز ارسال‌شده‌اش در همان بانک سند می‌خورد</small></div><button class="x" data-act="close" aria-label="بستن">×</button></div>
  ${L.length?`<div class="mvl bkunl">${L.map(s=>{const bk=acBank(s);let n=0,t=0;batches.forEach(b=>(b.items||[]).forEach(x=>{if(x.src===s.name&&x.st!=='fail'){n++;t+=+x.amount||0}}));
    return `<div class="mvs"><button type="button" class="acrow" data-act="bkUniM" data-id="${s.id}">${bk?bankBadge(bk,'lg'):`<span class="bkb lg" style="--bc:#64748b">${esc(userInit(s.name))}</span>`}<span class="tx"><b>${esc(s.name)}</b><small>${n?toFa(n)+' واریزی ارسال‌شده · '+fmt(t)+' تومان':'هنوز واریزی ارسال‌شده ندارد'}</small></span><em class="bkunb">وصل کردن</em></button></div>`}).join('')}</div>
  <div class="bkunh">${ic('info')}<span>اگر مانده آن بانک را قبلاً دستی درست کرده‌اید، بعد از وصل کردن یک بار «اصلاح موجودی» بزنید.</span></div>`:`<div class="xnone">همه منبع‌ها حساب بانکی دارند ✓</div>`}`}
ACT.bkUni=()=>{if(!can('src'))return;sheet(bkUniHTML())};
ACT.bkUniM=(d,e)=>{const so=sources.find(x=>String(x.id)===String(d.id));if(!so)return;const T=e&&e.target&&e.target.closest('button');
  popMenu(T,[['bkUniGo',ic('plus'),'حساب بانکی تازه «'+so.name+'»',{id:so.id,cu:''}],...srcLinkCands().map(c=>['bkUniGo',ic('bank'),cuName(c)+' · '+bfxMv(bkCuBal(c)),{id:so.id,cu:c.id}]),...(srcUsed(so)?[]:[['bkUniDel',ic('trash'),'حذف این منبع · استفاده نشده',{id:so.id}]])])};
ACT.bkUniDel=d=>{const so=sources.find(x=>String(x.id)===String(d.id));if(!so||!can('src')||srcUsed(so)||srcBk(so))return;askConfirm('منبع «'+so.name+'» حذف شود؟ هیچ واریزی‌ای با آن ثبت نشده است.','حذف',()=>{sources=sources.filter(z=>z!==so);saveS();logA('src','حذف منبع بدون استفاده',so.name);render();if(bkUniL().length)sheet(bkUniHTML());else closeSheet();toast('منبع حذف شد')})};
ACT.bkUniGo=d=>{const so=sources.find(x=>String(x.id)===String(d.id));if(!so||!can('src'))return;const c=srcLinkDo(so,d.cu?custs.find(z=>String(z.id)===String(d.cu)):null);if(!c)return;
  render();if(bkUniL().length)sheetKeep(bkUniHTML());else closeSheet();toast('«'+so.name+'» به «'+cuName(c)+'» وصل شد')};
function bkLinkRow(c){if(!c||!c.id||c.grp!=='بانک'||!can('src'))return '';const s=bkSrcOf(c);return `<button type="button" class="bklr" data-act="bkLinkM" data-cu="${c.id}"><span class="bkdi">${ic('list')}</span><span class="tx"><b>لیست‌های واریز</b><small>${s?'از «'+esc(s.name)+'» اینجا سند می‌خورد':'به هیچ بانکی وصل نیست'}</small></span><em>${s?'تغییر':'انتخاب'}</em></button>`}
ACT.bkLinkM=(d,e)=>{const c=custs.find(z=>String(z.id)===String(d.cu));if(!c)return;const T=e&&e.target&&e.target.closest('button');
  popMenu(T,[...ownL().map(s=>['bkLinkS',ic(bkSrcOf(c)&&String(c.srcId)===String(s.id)?'check':'bank'),s.name,{cu:c.id,s:s.id}]),bkSrcOf(c)?['bkLinkS',ic('x'),'قطع اتصال',{cu:c.id,s:''}]:null].filter(Boolean))};
ACT.bkLinkS=d=>{const c=custs.find(z=>String(z.id)===String(d.cu));if(!c)return;const now=new Date().toISOString();
  if(d.s===''||d.s==null){delete c.srcId;delete c.srcAt;c.srcNo=1}else{delete c.srcNo;const s=sources.find(z=>String(z.id)===String(d.s));if(!s)return;
    const other=bkCus().find(z=>z!==c&&String(z.srcId)===String(s.id));if(other){toast('«'+s.name+'» به حساب «'+cuName(other)+'» وصل است',true);return}
    if(String(c.srcId)!==String(s.id)){c.srcId=s.id;c.srcAt=now}}
  c.updatedAt=now;bkDepSync(c,1);saveCu();logA('cust','اتصال حساب بانک به لیست‌های واریز',cuName(c)+' ← '+((bkSrcOf(c)||{}).name||'قطع'));render();const lr=document.querySelector('#sheet .bklr');if(lr)lr.outerHTML=bkLinkRow(c);toast(bkSrcOf(c)?'وصل شد':'اتصال قطع شد')};
 


const stj=v=>Array.isArray(v)?'['+v.map(stj).join(',')+']':v&&typeof v==='object'?'{'+Object.keys(v).filter(k=>v[k]!==undefined).sort().map(k=>JSON.stringify(k)+':'+stj(v[k])).join(',')+'}':JSON.stringify(v===undefined?null:v);
function bkDup(c,f,now){const seen=new Map();let ch=0;for(const t of (c.txs||[]).slice().sort((a,b)=>String(a.id).localeCompare(String(b.id),'en',{numeric:true}))){if(t.del||!t[f])continue;const k=String(t[f]);if(seen.has(k)){t.del=true;t.delAt=now;t.delBy='خودکار';ch=1}else seen.set(k,t)}return ch}
function bkDepSync(c,noSave){const s=bkSrcOf(c),now=new Date().toISOString();let ch=0;const want=new Map();
   
  if(s){for(const b of batches)for(const x of b.items||[]){if(x.src!==s.name||x.st==='fail')continue;const at=x.sAt||b.createdAt||'';
      const k=String(b.id),o=want.get(k)||{R:[],date:b.pay||b.date||String(at).slice(0,10),at};const K=itImgs(b,x);
      o.R.push({m:'dls',amount:Math.round(+x.amount||0),nm:x.name||'',eid:x.id,src:s.name,...(x.tn?{tn:x.tn}:{}),...(K.length?{imgs:K,img:K[0]}:{})});want.set(k,o)}}
  bkDup(c,'bl',now)&&(ch=1);
  for(const t of c.txs||[]){if(t.del||!t.bl)continue;const w=want.get(String(t.bl));
    if(!w||!w.R.length){t.del=true;t.delAt=now;t.delBy='خودکار';ch=1;continue}
    if(stj(t.pays)!==stj(w.R)){t.pays=w.R;t.edAt=now;ch=1}want.delete(String(t.bl))}
  for(const [k,w] of want){if(!w.R.length)continue;(c.txs=c.txs||[]).push({id:nid++,type:'inv',dk:'in',no:invNext(),date:w.date,rate:0,mz:0,items:[],xr:[],tax:false,disc:0,sub:0,total:0,
    pays:w.R,note:'',bl:k,at:w.at||now,by:'خودکار',cn:cnNext(c)});ch=1}
  if(ch){c.lastAt=now;if(!noSave)audBg(()=>saveCu())}return ch}
function bkDepSyncAll(){let ch=lnkOrph();for(const c of bkCus()){if(bkSrcOf(c)||(c.txs||[]).some(t=>t.bl&&!t.del))ch+=bkDepSync(c,1);ch+=posDaySync(c)}if(ch)audBg(()=>saveCu());return ch}
 
function lnkUpgrade(c){let ch=0;for(const t of c.txs||[]){if(t.del||t.type!=='xf'||!t.inv||t.peer)continue;const C=custs.find(z=>String(z.id)===String(t.inv.cu)),T=C&&(C.txs||[]).find(z=>String(z.id)===String(t.inv.tx));
    const p=T&&(T.pays||[]).find(q=>String(q.xfId)===String(t.id));if(!p)continue;const r=+t.r||0;
    Object.assign(t,{type:'inv',dk:r<0?'in':'out',no:T.no,rate:0,mz:0,items:[],xr:[],tax:false,disc:0,sub:0,total:0,pays:[{m:'lnk',lm:p.m,amount:r,cuId:C.id,cuName:cuName(C),...(p.why?{why:p.why}:{})}],lk:{cu:C.id,tx:T.id},note:'',cn:cnNext(c)});
    delete t.inv;delete t.r;delete t.g;ch=1}
  if(ch)audBg(()=>saveCu());return ch}
 


function posDaySync(c){const now=new Date().toISOString();let ch=0;const D=new Map();
  for(const C of CU()){if(C===c)continue;for(const T of C.txs||[]){if(T.del||T.type!=='inv')continue;for(const p of T.pays||[]){if(p.m!=='pos'||!p.bk||String(p.cuId)!==String(c.id))continue;
      if(p.xfId!=null){const o=(c.txs||[]).find(z=>String(z.id)===String(p.xfId));if(o&&!o.del){o.del=true;o.delAt=now;o.delBy='خودکار'}delete p.xfId;ch=1}
      const k=T.date||String(T.at||now).slice(0,10);if(!D.has(k))D.set(k,[]);D.get(k).push({m:'lnk',lm:'pos',amount:-(+p.amount||0),cuId:C.id,cuName:cuName(C),lcu:C.id,ltx:T.id,no:T.no,...(p.imgs&&p.imgs.length?{imgs:p.imgs.slice(),img:p.imgs[0]}:{})})}}}
  bkDup(c,'pd',now)&&(ch=1);
  for(const t of c.txs||[]){if(t.del||!t.pd)continue;const R=D.get(t.pd);if(!R||!R.length){t.del=true;t.delAt=now;t.delBy='خودکار';ch=1;continue}
    if(stj(t.pays)!==stj(R)){t.pays=R;t.edAt=now;ch=1}D.delete(t.pd)}
  for(const [k,R] of D){ const od=(c.txs||[]).filter(z=>z.del&&z.pd===k&&z.delBy==='خودکار').pop();if(od){od.del=false;delete od.delAt;delete od.delBy;od.pays=R;od.edAt=now;ch=1;continue}
    (c.txs=c.txs||[]).push({id:nid++,type:'inv',dk:'in',no:invNext(),date:k,rate:0,mz:0,items:[],xr:[],tax:false,disc:0,sub:0,total:0,pays:R,note:'',pd:k,at:k+'T23:00:00.000Z',by:'خودکار',cn:cnNext(c)});ch=1}
  if(ch){c.lastAt=now}return ch}
function posDaySyncAll(noSave){let ch=lnkOrph();for(const c of bkCus())ch+=posDaySync(c);if(ch&&!noSave)audBg(()=>saveCu());return ch}


 
const bkNameBank=n=>{const W=nzName(toEn(n||'')).replace(/(^|\s)مهر(?=\s|$)/g,'$1مهر ایران').replace(/[()«»\-_,،.]/g,' ').split(/\s+/).filter(w=>w&&w!=='بانک');return BK_PICK.slice().sort((a,b)=>b.split(' ').length-a.split(' ').length||b.length-a.length).find(b=>{const B=nzName(b).split(/\s+/);for(let i=0;i+B.length<=W.length;i++)if(B.every((x,j)=>W[i+j]===x))return true;return false})||''};
const bkOfCu=c=>c?(bkNameBank(c.name||'')||c.bank||ibanBank(c.iban||'')||bankOfCard(c.card)||''):'';
function bkLogoFix(){let ch=0;for(const c of bkCus()){const b=bkNameBank(c.name||'')||ibanBank(c.iban||'')||bankOfCard(c.card)||'';if(b&&c.bank!==b){c.bank=b;c.updatedAt=new Date().toISOString();ch=1}}if(ch)audBg(()=>saveCu());return ch}
const bkLogo=b=>!!(b&&(BKL[b]||BKL[Object.keys(BKL).find(n=>canon(n)===canon(b))]));
const bkAvH=c=>{const b=bkOfCu(c);return bkLogo(b)?`<span class="c6a cul bxlogo bkav">${bankBadge(b,'lg')}</span>`:''};
const bkWmH=c=>{const b=c&&c.grp==='بانک'&&bkOfCu(c);return b&&bkLogo(b)?`<span class="bkwm" aria-hidden="true">${bankBadge(b,'wm')}</span>`:''};





function edDupFix(){const now=new Date().toISOString();let ch=0;
  for(const c of custs){if(c.sys||c.del||!(c.txs||[]).some(t=>t.edOf!=null&&!t.del))continue;const I=new Map((c.txs||[]).map(t=>[String(t.id),t]));
    const root=t=>{let g=0;while(t.edOf!=null&&I.has(String(t.edOf))&&g++<200)t=I.get(String(t.edOf));return String(t.id)};const G=new Map();
    for(const t of c.txs||[]){if(t.del||t.type!=='inv'||t.lk||t.pd||t.bl||t.bd)continue;const k=root(t);(G.get(k)||G.set(k,[]).get(k)).push(t)}
    for(const L of G.values()){if(L.length<2)continue;L.sort((a,b)=>String(b.at||'').localeCompare(String(a.at||''))||String(b.id).localeCompare(String(a.id),'en',{numeric:true}));
      L.slice(1).forEach(t=>{t.del=true;t.delAt=now;t.delBy='خودکار';t.dupOf=L[0].id;try{txLinked(c,t).forEach(x=>{if(!x.t.del){x.t.del=true;x.t.delAt=now;x.t.delBy='خودکار'}})}catch(_){}try{invDepOff(t)}catch(_){}ch++})}}
  return ch}


function noDupFix(){const G=new Map();let ch=0,eCh=0,bCh=0;
  for(const c of custs){if(c.sys||c.del)continue;for(const t of c.txs||[]){if(t.del||t.type!=='inv'||t.lk||t.bd||t.no==null)continue;const k=String(t.no);(G.get(k)||G.set(k,[]).get(k)).push({c,t})}}
  const key=o=>String(o.t.at0||o.t.at||''),L=[...G.values()].filter(z=>z.length>1).sort((a,b)=>(+a[0].t.no||0)-(+b[0].t.no||0));if(!L.length)return 0;
  let nx=docNoMax();
  for(const Z of L){Z.sort((a,b)=>(b.t.auto?1:0)-(a.t.auto?1:0)||key(a).localeCompare(key(b))||String(a.t.id).localeCompare(String(b.t.id),'en',{numeric:true}));
    Z.slice(1).forEach(({c,t})=>{if(t.auto)return;const old=t.no,nw=++nx;t.no0=old;t.no=nw;ch++;
      for(const y of custs)for(const m of y.txs||[])if(m.lk&&String(m.lk.tx)===String(t.id)&&String(m.lk.cu)===String(c.id))m.no=nw;
      if(!Z.some(o=>o.t!==t&&o.c===c)){const ids=new Set();for(const e of entries){if(e.wd&&String(e.wd.cu)===String(c.id)&&String(e.wd.no)===String(old)){e.wd.no=nw;if(String(e.code)===String(old))e.code=String(nw);ids.add(e.id);eCh++}}
        if(ids.size){for(const e of entries)if(e.splitOf!=null&&ids.has(e.splitOf)){if(String(e.code)===String(old))e.code=String(nw);ids.add(e.id)}for(const b of batches)for(const x of b.items||[])if(ids.has(x.id)&&String(x.code)===String(old)){x.code=String(nw);bCh++}}}
      for(const e of entries)for(const z of e.settles||[])if(z.byInv&&String(z.byInv.tx)===String(t.id)&&String(z.byInv.cu)===String(c.id)&&String(z.inv)===String(old)){z.inv=String(nw);if(z.note)z.note=String(z.note).replace(toFa(old),toFa(nw));eCh++}})}
  if(eCh)audBg(()=>saveE());if(bCh)audBg(()=>ls.set('m_batches',batches));return ch}
function lnkOrph(){const now=new Date().toISOString(),CI=new Map(custs.map(c=>[String(c.id),c]));let ch=0;try{ch+=edDupFix()}catch(_){}try{ch+=noDupFix()}catch(_){}
  const live=(cu,tx)=>{const C=CI.get(String(cu));if(!C||C.del)return false;const T=(C.txs||[]).find(z=>String(z.id)===String(tx));return !!(T&&!T.del)};
  for(const c of custs){if(c.sys)continue;for(const t of c.txs||[]){const src=t.type==='inv'&&t.lk?t.lk:t.type==='xf'&&t.inv?t.inv:null;if(!src)continue;const ok=live(src.cu,src.tx);
    if(!t.del&&!ok){t.del=true;t.delAt=now;t.delBy='خودکار';t.delSrc=1;ch++}
    else if(t.del&&t.delSrc&&ok){t.del=false;delete t.delSrc;delete t.delAt;delete t.delBy;ch++}}}
  return ch}


