function bfxCalc(){const t=+CK.bt||0,p=+CK.bp||0,cur=bfxCur(),neg=!!CK.bneg,T=neg?-t:t;return {cur,p,T,d:T-cur,F:T+p,ok:CK.bt!==''&&CK.bt!=null}} 
